// Verifies the TypeScript aggregations against independent pandas results
// (tests/reference.json, generated by preprocess/preprocess.py).
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { toDataset, type RawDataset, popcount } from '../src/lib/data';
import {
  allImages, countPatients, filterImages, findingBit, findingCounts, imagesPerPatient,
  imagesPerPatientCounts, overview, prevalenceByAgeSex, vennCounts, complexityByView,
  complexityByAge, anyFindingMask,
} from '../src/lib/compute';
import { DEFAULT_FILTERS, filtersFromQuery, filtersToQuery, toggleFinding, CLEARED_FILTERS } from '../src/lib/filters';

const raw = JSON.parse(readFileSync(resolve(__dirname, '../public/data/images.json'), 'utf8')) as RawDataset;
const ref = JSON.parse(readFileSync(resolve(__dirname, 'reference.json'), 'utf8'));
const ds = toDataset(raw);
const all = allImages(ds);
const nf = DEFAULT_FILTERS;

/** convert reference venn object (name keys) to region bitmask map for a selection */
function refRegions(obj: Record<string, number>, sel: string[]) {
  const m = new Map<number, number>();
  for (const [k, v] of Object.entries(obj)) {
    if (k === '__none__') continue;
    const names = k.split('+');
    m.set(names.reduce((acc, n) => acc | (1 << sel.indexOf(n)), 0), v);
  }
  return m;
}

describe('dataset integrity', () => {
  it('matches the CSV row and patient counts', () => {
    expect(ds.n).toBe(112120);
    expect(ds.nPatients).toBe(30805);
    expect(ds.n).toBe(ref.totals.images);
    expect(countPatients(ds, all)).toBe(ref.totals.patients);
  });
  it('flags implausible ages as missing', () => {
    expect(Array.from(ds.age).filter((a) => a < 0).length).toBe(ref.totals.missingAgeImages);
    expect(ds.age.reduce((m, a) => Math.max(m, a), 0)).toBeLessThanOrEqual(100);
  });
  it('popcount works', () => {
    expect(popcount(0)).toBe(0);
    expect(popcount(0b10110)).toBe(3);
  });
});

describe('overview', () => {
  const o = overview(ds);
  it('patients by recorded gender', () => {
    expect(o.patientsBySex.M).toBe(ref.totals.patientsBySex.M);
    expect(o.patientsBySex.F).toBe(ref.totals.patientsBySex.F);
    expect(o.patientsBySex.missing).toBe(0);
  });
  it('images by view position', () => {
    expect(o.imagesByView.PA).toBe(ref.totals.imagesByView.PA);
    expect(o.imagesByView.AP).toBe(ref.totals.imagesByView.AP);
  });
  it('every patient lands in exactly one age bin or missing', () => {
    const s = o.patientsByAge.reduce((a, b) => a + b.patients, 0) + o.patientsMissingAge;
    expect(s).toBe(ds.nPatients);
  });
  it('images-per-patient distribution sums to all patients / images', () => {
    expect(o.imagesPerPatient.reduce((a, b) => a + b.patients, 0)).toBe(ds.nPatients);
    expect(o.imagesPerPatient.reduce((a, b) => a + b.patients * b.images, 0)).toBe(ds.n);
    expect(o.imagesPerPatient.at(-1)!.images).toBe(184);
  });
  it('abnormal images = images minus No Finding', () => {
    expect(o.abnormalImages).toBe(ds.n - ref.totals.noFindingImages);
  });
});

describe('per-finding counts (images and patients, AP/PA)', () => {
  const fc = findingCounts(ds, all);
  it.each(Object.keys(ref.findings))('%s', (f) => {
    const r = fc.find((x) => x.finding === f)!;
    expect(r.images).toBe(ref.findings[f].images);
    expect(r.patients).toBe(ref.findings[f].patients);
    expect(r.PA).toBe(ref.findings[f].PA);
    expect(r.AP).toBe(ref.findings[f].AP);
    expect(r.PA + r.AP + r.otherView).toBe(r.images);
  });
  it('No Finding row', () => {
    expect(fc.at(-1)!.images).toBe(ref.totals.noFindingImages);
  });
});

describe('label complexity', () => {
  it('images by #findings and view match pandas', () => {
    const c = complexityByView(ds);
    for (const v of ['PA', 'AP'] as const)
      for (const [k, n] of Object.entries(ref.complexity[v])) expect(c[v][+k]).toBe(n);
    expect(c.max).toBe(9);
  });
  it('age × complexity covers every image with a valid age', () => {
    const rows = complexityByAge(ds);
    expect(rows.reduce((a, r) => a + r.total, 0)).toBe(ds.n - ref.totals.missingAgeImages);
    rows.forEach((r) => expect(r.counts.reduce((a: number, b: number) => a + b, 0)).toBe(r.total));
  });
});

describe('Venn regions', () => {
  const sel = ref.venn.selection as string[];
  it('3-set image regions are exact and partition all images', () => {
    const v = vennCounts(ds, all, sel, 'images');
    expect(v.regions).toEqual(refRegions(ref.venn.images, sel));
    expect(v.none).toBe(ref.venn.images.__none__);
    expect(v.denominator).toBe(ds.n);
    sel.forEach((f, i) => expect(v.totals[i]).toBe(ref.findings[f].images));
  });
  it('3-set patient regions (ever-had semantics)', () => {
    const v = vennCounts(ds, all, sel, 'patients');
    expect(v.regions).toEqual(refRegions(ref.venn.patients, sel));
    expect(v.none).toBe(ref.venn.patients.__none__);
    expect(v.denominator).toBe(ds.nPatients);
    sel.forEach((f, i) => expect(v.totals[i]).toBe(ref.findings[f].patients));
  });
  it('2-set regions', () => {
    const s2 = ['Cardiomegaly', 'Edema'];
    const v = vennCounts(ds, all, s2, 'images');
    expect(v.regions).toEqual(refRegions(ref.venn.pairImages, s2));
  });
  it('empty selection: everything is "none"', () => {
    const v = vennCounts(ds, all, [], 'images');
    expect(v.regions.size).toBe(0);
    expect(v.none).toBe(ds.n);
  });
});

describe('prevalence by age and recorded gender', () => {
  const bit = findingBit(ds, 'Effusion');
  it.each(['images', 'patients'] as const)('Effusion, 10-year bins, %s', (unit) => {
    const { series, excluded } = prevalenceByAgeSex(ds, all, bit, unit, 10);
    expect(excluded).toBe(ref.totals.missingAgeImages);
    const r = unit === 'images' ? ref.prevalenceEffusionImages : ref.prevalenceEffusionPatients;
    for (const s of series) {
      const key = s.sex === 0 ? 'M' : 'F';
      for (const p of s.points) {
        const e = r[key][p.bin] ?? { n: 0, k: 0 };
        expect([p.bin, p.n, p.k]).toEqual([p.bin, e.n, e.k]);
        if (p.n === 0) expect(p.rate).toBeNull();
      }
    }
  });
  it('any-finding mask counts abnormal images', () => {
    const { series } = prevalenceByAgeSex(ds, all, anyFindingMask(ds), 'images', 10);
    const k = series.flatMap((s) => s.points).reduce((a, p) => a + p.k, 0);
    expect(k).toBe(ds.n - ref.totals.noFindingImages - Array.from(ds.age).filter((a, i) => a < 0 && ds.mask[i]).length);
  });
});

describe('images per patient', () => {
  const pre = imagesPerPatientCounts(ds, all);
  it('all patients', () => {
    const r = imagesPerPatient(ds, pre, null);
    expect(r.bins).toEqual(ref.imagesPerPatientAll);
    expect(r.patients).toBe(ds.nPatients);
    expect(r.images).toBe(ds.n);
    expect(r.max).toBe(184);
  });
  it.each(['Hernia', 'Pneumonia', 'Infiltration'])('patients with %s', (f) => {
    const r = imagesPerPatient(ds, pre, findingBit(ds, f));
    expect(r.bins).toEqual(ref.imagesPerPatient[f]);
    expect(r.patients).toBe(ref.findings[f].patients);
  });
});

describe('shared filters', () => {
  const f = { ...nf, sex: 'F' as const, view: 'AP' as const, ageMin: 20, ageMax: 39 };
  const idx = filterImages(ds, f);
  const R = ref.filtered_F_AP_20_39;
  it('filtered image/patient denominators', () => {
    expect(idx.length).toBe(R.images);
    expect(countPatients(ds, idx)).toBe(R.patients);
  });
  it('filtered per-finding counts', () => {
    const fc = findingCounts(ds, idx);
    for (const [name, e] of Object.entries<any>(R.findings)) {
      const r = fc.find((x) => x.finding === name)!;
      expect([name, r.images, r.patients, r.AP, r.PA]).toEqual([name, e.images, e.patients, e.AP, e.PA]);
    }
  });
  it('filtered Venn and images-per-patient', () => {
    const sel = ref.venn.selection as string[];
    expect(vennCounts(ds, idx, sel, 'images').regions).toEqual(refRegions(R.venn, sel));
    const r = imagesPerPatient(ds, imagesPerPatientCounts(ds, idx), findingBit(ds, 'Effusion'));
    expect(r.bins).toEqual(R.ipp_Effusion);
  });
  it('view filter can be ignored (AP/PA page)', () => {
    expect(filterImages(ds, f, { ignoreView: true }).length).toBeGreaterThan(idx.length);
  });
  it('full age range keeps images with missing age; narrowed range drops them', () => {
    expect(filterImages(ds, nf).length).toBe(ds.n);
    expect(filterImages(ds, { ...nf, ageMin: 0, ageMax: 99 }).length).toBe(
      ds.n - ref.totals.missingAgeImages - Array.from(ds.age).filter((a) => a === 100).length,
    );
  });
  it('a filter combination with no matches returns empty results safely', () => {
    const e = filterImages(ds, { ...nf, ageMin: 100, ageMax: 100, sex: 'F', view: 'PA' });
    const v = vennCounts(ds, e, ['Hernia'], 'images');
    expect(v.denominator).toBe(e.length);
    const r = imagesPerPatient(ds, imagesPerPatientCounts(ds, e), findingBit(ds, 'Hernia'));
    expect(r.median).toBeNull();
    expect(r.patients).toBe(0);
  });
  it('finding selection is capped at 3 and round-trips through the URL', () => {
    let s = CLEARED_FILTERS;
    for (const n of ['Hernia', 'Edema', 'Mass', 'Nodule']) s = toggleFinding(s, n);
    expect(s.findings).toEqual(['Hernia', 'Edema', 'Mass']);
    s = { ...s, sex: 'M', view: 'PA', ageMin: 30, ageMax: 60 };
    expect(filtersFromQuery(filtersToQuery(s), ds.findings)).toEqual(s);
    expect(filtersFromQuery('f=Bogus,Hernia,Hernia&age=90-10', ds.findings)).toEqual({
      ...DEFAULT_FILTERS, findings: ['Hernia'], ageMin: 10, ageMax: 90,
    });
  });
});
